# Generated by personalServerNotes/scripts/npm-oidc/rollout.mjs (ROTATE-1 D-ROT-5). Edit the template, not this copy.
# Publishes through GitHub Actions trusted publishing (OIDC): pushes the release commit and a
# v<version> tag, then waits until the version is on the registry. No npm token is used.
[CmdletBinding()]
param(
  [Parameter(Mandatory = $true)][string]$RepoRoot,
  [Parameter(Mandatory = $true)][string]$PackageName,
  [Parameter(Mandatory = $true)][string]$Version,
  [int]$TimeoutSeconds = 900
)
$ErrorActionPreference = "Stop"
$npmCmd = if ($env:OS -match "Windows") { "npm.cmd" } else { "npm" }
$tag = "v$Version"

& git -C $RepoRoot push origin HEAD
if ($LASTEXITCODE -ne 0) { Write-Host "git push failed - nothing published." -ForegroundColor Red; exit 1 }
& git -C $RepoRoot tag $tag
if ($LASTEXITCODE -ne 0) { Write-Host "git tag $tag failed - nothing published." -ForegroundColor Red; exit 1 }
& git -C $RepoRoot push origin $tag
if ($LASTEXITCODE -ne 0) { Write-Host "git push of $tag failed - nothing published." -ForegroundColor Red; exit 1 }

$remote = (& git -C $RepoRoot remote get-url origin) -replace '\.git$', ''
Write-Host "Tag $tag pushed; GitHub Actions publishes it: $remote/actions" -ForegroundColor Cyan

$deadline = (Get-Date).AddSeconds($TimeoutSeconds)
while ((Get-Date) -lt $deadline) {
  $seen = & $npmCmd view "$PackageName@$Version" version 2>$null
  if ($seen -eq $Version) { Write-Host "$PackageName@$Version is live on npm." -ForegroundColor Green; exit 0 }
  Write-Host ("[{0:HH:mm:ss}] waiting for $PackageName@$Version on npm..." -f (Get-Date))
  Start-Sleep -Seconds 20
}
Write-Host "Timed out after $TimeoutSeconds s: $PackageName@$Version not on npm. Check $remote/actions" -ForegroundColor Red
exit 1
